insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0002-0000-4000-8000-00000000000e', 'en', null, 'Introduction to AI & Machine Learning', 'A plain-language first tour of what artificial intelligence and machine learning actually are — how models learn from data, where they fail, and how to use them responsibly. Topic structure adapted from the Artificial Intelligence knowledge area of the ACM Computing Curricula.', null, 'work', 14, true, 'technology', '{bbbb0002-0000-4000-8000-000000000002}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0002-0000-4000-8000-00000000000e', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"Artificial intelligence is best described as…","options":["software that is conscious and self-aware","systems that perform tasks we associate with human intelligence","any computer program at all","robots with physical bodies"],"answer":1,"explanation":"AI is about performing tasks that seem to need intelligence — not consciousness — see ''What AI is (and isn''t)''."},{"prompt":"Most AI in use today is best called…","options":["general AI","narrow AI","superintelligence","artificial consciousness"],"answer":1,"explanation":"Today''s systems are narrow: good at specific tasks, not general reasoning — see ''What AI is (and isn''t)''."},{"prompt":"In machine learning, a model mainly learns from…","options":["rules a programmer writes by hand","patterns in example data","the internet reading its mind","random guessing only"],"answer":1,"explanation":"ML fits patterns from data rather than following hand-written rules — see ''How machine learning works''."},{"prompt":"A ''feature'' in machine learning is…","options":["a bug in the code","a measurable input the model uses","the final prediction","the marketing name of a product"],"answer":1,"explanation":"Features are the input variables — see ''How machine learning works''."},{"prompt":"Learning from labeled examples (input paired with the correct answer) is called…","options":["unsupervised learning","supervised learning","reinforcement learning","deep sleep"],"answer":1,"explanation":"Labels present = supervised learning — see ''Three ways machines learn''."},{"prompt":"A neural network is loosely inspired by…","options":["how planets orbit","layers of connected units passing signals","a spreadsheet formula","a single if-statement"],"answer":1,"explanation":"Layers of weighted units — see ''Neural networks & deep learning''."},{"prompt":"A large language model generates text by…","options":["looking up sentences in a database","predicting likely next tokens one at a time","copying a human typing live","true understanding of meaning"],"answer":1,"explanation":"LLMs predict the next token repeatedly — see ''Large language models''."},{"prompt":"If training data reflects past human bias, a model will tend to…","options":["automatically correct it","reproduce or amplify it","ignore the data","become fairer than people"],"answer":1,"explanation":"Models learn the biases in their data — see ''How machine learning works'' and the applied project."}]}'::jsonb, null, 10),
  (2, 'What AI is (and isn''t)', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Define artificial intelligence in plain terms and tell narrow AI apart from general AI. Warm-up: from the diagnostic, is a spam filter ''narrow'' or ''general'' AI?"},{"heading":"The idea","text":"*Artificial intelligence* is a broad field: building systems that do tasks we usually associate with human intelligence — recognizing images, translating, recommending, planning. The term dates to a 1956 workshop, and the field has gone through waves of optimism and ''AI winters'' since. A key split: *narrow AI* does one job well (spam filtering, route-finding, face unlock); *general AI* would reason flexibly across any task the way a person can. Despite headlines, everything shipped in 2026 is narrow AI — powerful, but not conscious, not self-aware, and not general."},{"heading":"Worked example","text":"Trace a spam classifier deciding on one email. It reads *features* — does the subject contain ''free money'', how many links, is the sender known? It has learned from past examples that these features raise the odds of spam. It outputs a score, say 0.92, and because 0.92 is above its 0.5 threshold it labels the email ''spam''. No understanding of the message — just a learned mapping from features to a score."},{"heading":"Your turn","text":"Label each as narrow AI, general AI, or not AI: (1) a chess engine, (2) a calculator adding two numbers, (3) a system that reasons about any problem a human can, (4) a voice assistant setting a timer. Answers: 1-narrow AI, 2-not AI (fixed rules, no learning), 3-general AI (does not yet exist), 4-narrow AI."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming today''s AI ''understands'' like a person — it maps inputs to outputs from data. Mistake: calling every program ''AI'' (a plain calculator isn''t). Exit: (a) Which type of AI is in use today? (b) Does general AI exist yet? Answers: narrow AI; no."}]}'::jsonb, 'Narrow AI = one task; general AI = human-level across tasks and does not yet exist.', 11),
  (3, 'How machine learning works', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain how a model learns from data and why testing on unseen data matters. Warm-up: what is a ''feature''?"},{"heading":"The idea","text":"Machine learning flips normal programming. Instead of writing rules by hand, you show a *model* many examples and let it find the pattern. Each example is described by *features* (measurable inputs) and, in supervised learning, a *label* (the right answer). *Training* adjusts the model''s internal numbers so its predictions get closer to the labels. Crucially, you then test on *held-out* data the model never saw — because a model that memorizes its training set but fails on new data is *overfitting*."},{"heading":"Worked example","text":"Trace a classifier that predicts if a fruit is a lemon or a lime from two features: color and weight. During training it sees hundreds of labeled fruits and learns a rough boundary — ''yellow and light → lemon''. Now a new fruit arrives: yellowish, light. The model checks it against the learned boundary, lands on the lemon side, and predicts ''lemon''. It is not certain; it is going with the pattern that fit the training data best."},{"heading":"Your turn","text":"For a model predicting house price: (1) name two plausible features, (2) what is the label, (3) why hold out some houses for testing, (4) what is it called when a model aces training data but fails on new data? Answers: 1-e.g. square metres and number of rooms; 2-the sale price; 3-to check it generalizes, not memorizes; 4-overfitting."},{"heading":"Common mistakes & exit ticket","text":"Mistake: judging a model only on data it trained on — that hides overfitting. Mistake: forgetting that biased or unrepresentative training data produces biased predictions. Exit: (a) Rules are written by hand or learned from data in ML? (b) Why test on unseen data? Answers: learned from data; to measure whether it generalizes."}]}'::jsonb, 'Pipeline: data → features → model → prediction; then check on data it never saw.', 12),
  (4, 'Three ways machines learn', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Tell supervised, unsupervised, and reinforcement learning apart. Warm-up: if every example comes with the correct answer attached, which kind is it?"},{"heading":"The idea","text":"There are three broad styles. *Supervised learning* uses labeled examples — input paired with the right answer — to learn a mapping (spam/not-spam, price prediction). *Unsupervised learning* has no labels; it finds structure on its own, such as grouping similar customers into *clusters*. *Reinforcement learning* has no fixed answers either; an agent tries actions, gets *rewards* or penalties, and gradually learns a strategy — the way a program learns to play a game by scoring points. Most everyday business ML is supervised, because labels make evaluation clear."},{"heading":"Worked example","text":"Trace how each would tackle customer data. Supervised: given past customers labeled ''churned'' or ''stayed'', learn to predict who leaves next. Unsupervised: with no labels, group customers into segments by behavior and let a human interpret the groups. Reinforcement: an agent picks which offer to send, sees whether the customer buys (reward), and updates its policy to send better offers over time."},{"heading":"Your turn","text":"Classify each: (1) labeling emails spam/not-spam from examples, (2) grouping news articles by topic with no labels, (3) a robot learning to walk by trial and reward, (4) predicting tomorrow''s temperature from labeled history. Answers: 1-supervised, 2-unsupervised, 3-reinforcement, 4-supervised."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking clustering ''knows'' what the groups mean — a human still has to interpret them. Mistake: assuming reinforcement learning needs labeled answers — it learns from rewards instead. Exit: (a) Which style uses labels? (b) Which learns from rewards? Answers: supervised; reinforcement."}]}'::jsonb, 'Supervised = labeled; unsupervised = no labels; reinforcement = reward from trial and error.', 12),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Everything shipped as AI in 2026 is best described as…","options":["general AI","narrow AI","conscious AI","superintelligence"],"answer":1,"explanation":"Powerful but task-specific: narrow AI."},{"prompt":"In supervised learning, each training example includes…","options":["only inputs","an input and its correct label","a reward signal","nothing but rewards"],"answer":1,"explanation":"Labels are what make it supervised."},{"prompt":"A model that scores well on training data but poorly on new data is…","options":["underfitting","overfitting","generalizing","clustering"],"answer":1,"explanation":"It memorized instead of generalizing — overfitting."},{"prompt":"Grouping unlabeled data into similar sets is…","options":["supervised learning","clustering (unsupervised)","reinforcement learning","overfitting"],"answer":1,"explanation":"No labels, find structure: clustering."},{"prompt":"A ''feature'' is…","options":["the model''s output","a measurable input variable","a reward","the training loop"],"answer":1,"explanation":"Features are the inputs the model reads."},{"prompt":"If training data carries historical bias, the model will most likely…","options":["remove the bias","reproduce or amplify the bias","refuse to run","become random"],"answer":1,"explanation":"Models reflect the data they learn from."}]}'::jsonb, null, 8),
  (6, 'Neural networks & deep learning', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe, without the math, what a neural network is and what makes it ''deep''. Warm-up: roughly, what does a network adjust while it trains?"},{"heading":"The idea","text":"A *neural network* is layers of simple units. Each unit takes numbers in, multiplies them by *weights*, adds them up, and passes the result through a simple function to the next layer. Training nudges those weights, over many examples, so the final output matches the labels better — a process called *gradient descent*. *Deep learning* just means a network with many layers, which lets it learn features in stages: early layers might catch edges in an image, later layers whole shapes. Depth is powerful but costly — it needs lots of data and computation, and the result is hard to interpret."},{"heading":"Worked example","text":"Trace a tiny network deciding if an image is a cat. Layer one detects edges and colors. Layer two combines edges into parts — ears, whiskers, eyes. The final layer weighs those parts and outputs a probability, say 0.88 ''cat''. If the training label was ''cat'', the error is small and weights barely change; if it was ''dog'', the error flows backward and weights shift so next time the same picture leans more ''dog''. Repeat over millions of images."},{"heading":"Your turn","text":"(1) What does a network adjust during training? (2) What makes a network ''deep''? (3) Name one cost of deep learning. (4) True or false: deep networks are easy to interpret step by step. Answers: 1-its weights; 2-having many layers; 3-lots of data/compute (or low interpretability); 4-false."},{"heading":"Common mistakes & exit ticket","text":"Mistake: believing a neural network ''thinks'' like a brain — the brain analogy is loose; it is math on weights. Mistake: assuming more layers is always better (it can overfit and waste resources). Exit: (a) ''Deep'' refers to what? (b) What flows backward to update weights? Answers: many layers; the error (gradient)."}]}'::jsonb, 'Weights are the numbers a network tunes during training; ''deep'' just means many layers.', 12),
  (7, 'Large language models', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain in plain terms how a large language model produces text, and why fluent output can still be wrong. Warm-up: does an LLM look answers up, or predict them?"},{"heading":"The idea","text":"A *large language model* (LLM) is a deep neural network trained on huge amounts of text to do one deceptively simple thing: predict the next *token* (a word or word-piece). Given your prompt, it estimates which token is most likely next, adds it, and repeats — generating text one piece at a time. Because it learned statistical patterns of language, it is fluent, but it has no built-in fact-checker. When it produces confident, plausible, but false statements, that is a *hallucination*. LLMs also reflect biases and gaps in their training text, and their knowledge has a cutoff date unless connected to live tools."},{"heading":"Worked example","text":"Trace the model completing ''The capital of France is''. It has seen that phrase followed by ''Paris'' overwhelmingly often, so ''Paris'' gets the highest probability and is chosen. Now trace ''The capital of the fictional country of Zborvia is''. There is no fact to recall, but the pattern ''The capital of X is …'' still demands a plausible-sounding place name — so it may confidently invent one. Same mechanism, but the second output is a hallucination."},{"heading":"Your turn","text":"(1) What unit does an LLM predict? (2) Does fluent text guarantee it is correct? (3) What is a confident but false answer called? (4) Name one reason an LLM might be out of date. Answers: 1-the next token; 2-no; 3-a hallucination; 4-a training cutoff (no access to newer information)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating an LLM as a search engine or database of facts — it generates, it does not look up. Mistake: trusting fluent output without verifying important claims. Exit: (a) One token at a time — true or false? (b) Should you verify facts from an LLM? Answers: true; yes, especially anything that matters."}]}'::jsonb, 'An LLM predicts the next token; fluent text is not the same as being correct.', 13),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"model","translation":"a system that has learned a pattern from data and uses it to make predictions","example":"The trained model predicts whether an email is spam."},{"term":"feature","translation":"a measurable input variable the model uses to make a decision","example":"Word counts and links can be features for spam detection."},{"term":"supervised learning","translation":"learning from examples that are labeled with the correct answer","example":"Spam filtering is usually supervised learning."},{"term":"overfitting","translation":"when a model memorizes its training data and fails on new data","example":"High training accuracy but poor real-world accuracy suggests overfitting."},{"term":"token","translation":"a word or word-piece that a language model reads and predicts","example":"An LLM builds text one token at a time."},{"term":"hallucination","translation":"a confident but false or made-up output from a model","example":"The chatbot''s invented citation was a hallucination."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"During training, a neural network adjusts its…","options":["labels","weights","features","tokens"],"answer":1,"explanation":"Weights are the tunable numbers."},{"prompt":"''Deep'' in deep learning refers to…","options":["deep meaning","many layers","large hard drives","slow training"],"answer":1,"explanation":"Many layers stacked."},{"prompt":"A large language model generates text by…","options":["retrieving stored sentences","predicting the next token repeatedly","asking a human","translating from code"],"answer":1,"explanation":"Next-token prediction, one piece at a time."},{"prompt":"A confident but false model output is called a…","options":["feature","hallucination","cluster","reward"],"answer":1,"explanation":"Plausible but wrong: a hallucination."},{"prompt":"Fluent LLM output means the content is…","options":["always correct","not necessarily correct","always false","human-written"],"answer":1,"explanation":"Fluency is not accuracy — verify claims."},{"prompt":"One honest limitation of today''s AI is that it…","options":["is conscious","reflects biases in its training data","never makes mistakes","understands like a human"],"answer":1,"explanation":"Models inherit the biases and gaps of their data."}]}'::jsonb, null, 8),
  (10, 'Applied project: scope an ML use case', 'writing', '{"sections":[{"heading":"The task","text":"Pick one realistic machine-learning use case from your own work or daily life (for example: flagging fraudulent transactions, sorting support tickets, or recommending articles). You will not build it — you will scope it honestly, including where it could go wrong."},{"heading":"Milestones","text":"1) State the task in one sentence and say whether it is supervised, unsupervised, or reinforcement learning. 2) Describe the data you would need: what features, what labels (if any), and where the data comes from. 3) Name at least one way the data could be biased or unrepresentative. 4) List two concrete risks of getting a prediction wrong and who is affected. 5) Decide what a human should still review before the output is acted on."},{"heading":"Self-check rubric","text":"✔ The task and learning type are stated clearly. ✔ Features and labels are named, with an honest source for the data. ✔ You identified a specific bias risk, not just ''it might be biased''. ✔ Wrong-prediction harms are concrete and tied to real people. ✔ You defined a human-in-the-loop checkpoint. If all five hold, you have scoped AI the way a responsible practitioner does — usefulness first, limits and harms in plain view."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0002-0000-4000-8000-00000000000e' and l.position = v.pos
);
